static ssize_t pblk_sysfs_luns_show ( struct pblk * pblk , char * page ) { struct nvm_tgt_dev * dev = pblk -> dev ; struct nvm_geo * geo = & dev -> geo ; struct pblk_lun * rlun ; ssize_t sz = 0 ; int i ; for ( i = 0 ; i < geo -> nr_luns ; i ++ ) { int active = 1 ; rlun = & pblk -> luns [ i ] ; sz += snprintf ( page + sz , PAGE_SIZE - sz , "pblk: pos:%d, ch:%d, lun:%d - %d\n" , i , rlun -> bppa . g . ch , rlun -> bppa . g . lun , active ) ; } return sz ; } 